#include "stdafx.h"#include "HMATH.h"KMATH::KMATH(): m_CurParameterID(-1), m_ReadParams( 0 ){}static LPCSTR s_MyParameters[]={  "Equation",};BOOL KMATH::OnParsingSingleText( std::string &szText, RECTL *rc ){  if( m_CurParameterID!=-1 )  {    CStringA s;    if( !s.IsEmpty() )      m_settings.push_back( s.GetBuffer() );    m_CurParameterID = -1;    m_ReadParams++;    return TRUE;  }  for( int i=0; i<_countof(s_MyParameters); i++ )  {    if( szText.find(s_MyParameters[i])==0 )    {      m_CurParameterID = i;      return TRUE;    }  }  if( 1==m_ReadParams )  {    AddParam( s_MyParameters[0], szText.c_str() );    m_settings.push_back( szText.c_str() );    ++m_ReadParams;    m_CurParameterID = 2;    return TRUE;  }  if( szText==" " )  {    return TRUE;  }  return FALSE;}